    result = normalize_path(None, allow_empty=True)
    assert result == ""

def test_normalize_path_empty_path_not_allow_empty():
    with pytest.raises(ValueError, match="path is required"):
        normalize_path(None)

def test_normalize_path_relative_path_without_base():
